mapper.select:
select t.dateKey, (
    select count(*) from user where create_time <= str_to_date(t.dateKey, '%Y-%m-%d')
) as total from (
    select DATE_FORMAT(create_time, '%Y-%m-%d') as dateKey from user
    where create_time >= #{beginTime} and create_time <= #{endTime}
    group by dateKey
) t order by t.dateKey
